const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Init Run" } });

// Reset per-run counters at the START — workflow static data persists across
// executions; a run that crashed before Code: Build Summary must not carry
// stale counts into the next run.
const staticData = $getWorkflowStaticData('global');
staticData.checked = 0;
staticData.path_repaired = 0;
staticData.deleted_orphan = 0;
staticData.deleted_cascade_banktx = 0;
staticData.deleted_orphan_banktx = 0;
staticData.thumbnail_files_removed = 0;
staticData.done_events_published = 0;
staticData.skipped_ok = 0;
staticData._cascaded_banktx_uuids = {};

// Which trigger fired? Read the trigger nodes by NAME — n8n throws for a node
// that did not execute in this run (proven pattern, see
// alice-dms-image-description-backfill Code: Init Run). Do NOT read
// $input.first() here: the upstream lock node returns a fresh object without
// body/query (the PROJ-92 bug).
let firedNode = null;
try { if ($('Schedule Trigger: Monthly').first()) firedNode = 'schedule'; } catch(e) {}
try { if (!firedNode && $('Webhook: POST /alice-dms-reconcile').first()) firedNode = 'webhook'; } catch(e) {}
const fromSchedule = firedNode === 'schedule';

let body = {}, query = {};
if (!fromSchedule) {
  try {
    const webhookItem = $('Webhook: POST /alice-dms-reconcile').first().json;
    body = webhookItem.body || {};
    query = webhookItem.query || {};
  } catch(e) {}
}

let trigger, mode, maxRuntimeSeconds;
if (fromSchedule) {
  trigger = 'schedule';
  mode = 'confirm';           // schedule always executes — no schedule dry-run
  maxRuntimeSeconds = 3600;   // fixed 1h window, finishes before the 02:00 UTC processor
} else {
  trigger = 'webhook';
  const confirmRaw = body.confirm !== undefined ? body.confirm : query.confirm;
  mode = (confirmRaw === true || confirmRaw === 'true') ? 'confirm' : 'dry-run';
  const rawLimit = body.time_limit_seconds !== undefined ? body.time_limit_seconds : query.time_limit_seconds;
  const parsed = parseInt(rawLimit, 10);
  maxRuntimeSeconds = (!isNaN(parsed) && parsed > 0) ? parsed : null;
}

logger.info(`[reconcile] Init: trigger=${trigger} mode=${mode} max_runtime_seconds=${maxRuntimeSeconds === null ? 'none' : maxRuntimeSeconds}`);
return [{ json: { trigger, mode, max_runtime_seconds: maxRuntimeSeconds, window_start: Date.now() } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Acquire Lock" } });
const redis = require('redis');
const crypto = require('crypto');
// Same lock key as alice-dms-processor / the other DMS backfills — reconcile
// and the nightly processor must never write concurrently (BankStatement
// delete vs. the processor re-writing its children).
const LOCK_KEY = 'alice:dms:processor:lock:run';
const LOCK_TTL_MS = 3900000; // 65 min — TTL fallback if the workflow hard-crashes (>= the 3600s schedule window)

const run = $input.first().json;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
const ownerToken = crypto.randomUUID();
let acquired = false;
try {
  await client.connect();
  const res = await client.set(LOCK_KEY, JSON.stringify({ owner: ownerToken, workflow: 'alice-dms-reconcile', started_at: new Date().toISOString() }), { NX: true, PX: LOCK_TTL_MS });
  acquired = (res === 'OK');
} catch(e) {
  logger.info('[reconcile] Lock acquire error: ' + e.message + ' — failing closed (skip run)');
  acquired = false;
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { ...run, _lock_acquired: acquired, lock_owner: acquired ? ownerToken : null } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Respond Locked" } });
const run = $input.first().json;
logger.info('[reconcile] Run skipped: lock alice:dms:processor:lock:run is already held (nightly processor or another backfill).');
return [{ json: { status: 'skipped', mode: run.mode, trigger: run.trigger, stopped_reason: 'locked', message: 'Lauf bereits aktiv', checked: 0, path_repaired: 0, deleted_orphan: 0, deleted_cascade_banktx: 0, deleted_orphan_banktx: 0, thumbnail_files_removed: 0, done_events_published: 0, skipped_ok: 0, remaining: null } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Load Redis Maps" } });
const redis = require('redis');
const run = $input.first().json;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

let pathToHash = {};
let redisOk = false;
try {
  await client.connect();
  pathToHash = await client.hGetAll('alice:dms:path_to_hash') || {};
  redisOk = true;
} catch(e) {
  logger.warn('[reconcile] Could not load alice:dms:path_to_hash: ' + e.message + ' — every object will be treated as fail-safe (skipped_ok)');
  pathToHash = {};
  redisOk = false;
} finally {
  await client.quit().catch(() => {});
}

// hash -> [paths] reverse index, built once from path_to_hash so per-object
// classification does not hit Redis again for the common case. hash_to_paths:*
// sets are only consulted as a fallback inside Code: Process Object.
const hashToPaths = {};
for (const [p, h] of Object.entries(pathToHash)) {
  if (!h) continue;
  (hashToPaths[h] = hashToPaths[h] || []).push(p);
}

logger.info(`[reconcile] Redis maps loaded: redis_ok=${redisOk} path_to_hash entries=${Object.keys(pathToHash).length} distinct hashes=${Object.keys(hashToPaths).length}`);
return [{ json: { ...run, _redis_ok: redisOk, _path_to_hash: pathToHash, _hash_to_paths: hashToPaths } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Query Weaviate" } });
const axios = require('axios');
const run = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';
const LIMIT = 100;

// File-based collections + BankTransaction. Email is out of scope (PROJ-98).
// Image uses snake_case field names; everything else camelCase.
const FILE_COLLECTIONS = ['Invoice', 'BankStatement', 'Document', 'SecuritySettlement', 'Contract', 'Image'];

function fieldsFor(collection) {
  if (collection === 'Image') return '_additional { id } file_path file_hash file_name file_type additionalPaths';
  return '_additional { id } filePath fileHash fileName fileType additionalPaths';
}
function isMissingFieldError(errors, field) {
  try { const s = JSON.stringify(errors); return s.includes('Cannot query field') && s.includes(field); } catch(e) { return false; }
}

const work = [];

// --- file-based collections ---
for (const collection of FILE_COLLECTIONS) {
  const isImage = collection === 'Image';
  let cursor = null;
  let includeThumb = true;
  let includeAdditional = true;
  while (true) {
    const cursorClause = cursor ? `, after: "${cursor}"` : '';
    let coreFields = fieldsFor(collection);
    if (!includeAdditional) coreFields = coreFields.replace(' additionalPaths', '');
    const thumbClause = includeThumb ? ' thumbnail_path' : '';
    const gql = `{ Get { ${collection}(limit: ${LIMIT}${cursorClause}) { ${coreFields}${thumbClause} } } }`;
    let results;
    try {
      const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
      if (r.data?.errors) {
        if (includeThumb && isMissingFieldError(r.data.errors, 'thumbnail_path')) { includeThumb = false; continue; }
        if (includeAdditional && isMissingFieldError(r.data.errors, 'additionalPaths')) { includeAdditional = false; continue; }
        logger.warn(`[reconcile] GraphQL error for ${collection}: ${JSON.stringify(r.data.errors)}`);
        break;
      }
      results = r.data?.data?.Get?.[collection] || [];
    } catch(e) {
      logger.warn(`[reconcile] Request failed for ${collection}: ${e.message}`);
      break;
    }
    if (results.length === 0) break;
    for (const doc of results) {
      work.push({
        weaviate_uuid: doc._additional?.id,
        collection,
        kind: 'file',
        file_path: (isImage ? doc.file_path : doc.filePath) || null,
        file_hash: (isImage ? doc.file_hash : doc.fileHash) || null,
        file_name: (isImage ? doc.file_name : doc.fileName) || null,
        file_type: (isImage ? doc.file_type : doc.fileType) || null,
        additional_paths: Array.isArray(doc.additionalPaths) ? doc.additionalPaths : [],
        thumbnail_path: doc.thumbnail_path || null
      });
    }
    if (results.length < LIMIT) break;
    cursor = results[results.length - 1]?._additional?.id;
    if (!cursor) break;
  }
  const c = work.filter(w => w.collection === collection).length;
  logger.info(`[reconcile] ${collection}: ${c} objects queued`);
}

// --- BankTransaction (parent-existence check only) ---
{
  let cursor = null;
  while (true) {
    const cursorClause = cursor ? `, after: "${cursor}"` : '';
    const gql = `{ Get { BankTransaction(limit: ${LIMIT}${cursorClause}) { _additional { id } parentStatementId } } }`;
    let results;
    try {
      const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
      if (r.data?.errors) { logger.warn(`[reconcile] GraphQL error for BankTransaction: ${JSON.stringify(r.data.errors)}`); break; }
      results = r.data?.data?.Get?.BankTransaction || [];
    } catch(e) {
      logger.warn(`[reconcile] Request failed for BankTransaction: ${e.message}`);
      break;
    }
    if (results.length === 0) break;
    for (const doc of results) {
      work.push({
        weaviate_uuid: doc._additional?.id,
        collection: 'BankTransaction',
        kind: 'banktx',
        parent_statement_id: doc.parentStatementId || null
      });
    }
    if (results.length < LIMIT) break;
    cursor = results[results.length - 1]?._additional?.id;
    if (!cursor) break;
  }
  const c = work.filter(w => w.collection === 'BankTransaction').length;
  logger.info(`[reconcile] BankTransaction: ${c} objects queued`);
}

const total = work.length;
logger.info(`[reconcile] Total objects to check: ${total}`);
// The Redis maps stay on Code: Load Redis Maps' output — Code: Process Object
// reads them by node name. Do NOT copy them onto every work item (the
// path_to_hash map has thousands of entries; duplicating it per object blows
// up memory).
const common = { _empty: total === 0, total_objects: total, trigger: run.trigger, mode: run.mode, max_runtime_seconds: run.max_runtime_seconds, window_start: run.window_start, lock_owner: run.lock_owner, _redis_ok: run._redis_ok };
if (total === 0) return [{ json: { ...common } }];
return work.map(w => ({ json: { ...w, ...common } }));

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Process Object" } });
const axios = require('axios');
const fs = require('fs');
const redis = require('redis');

const item = $input.first().json;
const run = $('Code: Query Weaviate').first().json;
const maps = $('Code: Load Redis Maps').first().json;
const WEAVIATE = 'http://weaviate:8080';
const THUMBNAILER = 'http://alice-dms-thumbnailer:8004';
const mode = run.mode;                 // 'dry-run' | 'confirm'
const confirm = mode === 'confirm';
const redisOk = maps._redis_ok === true;
const pathToHash = maps._path_to_hash || {};
const hashToPaths = maps._hash_to_paths || {};
const staticData = $getWorkflowStaticData('global');
staticData.checked = (staticData.checked || 0) + 1;
function bump(k, n) { staticData[k] = (staticData[k] || 0) + (n === undefined ? 1 : n); }

const SHA256_RE = /^[a-f0-9]{64}$/i;
const uuid = item.weaviate_uuid;
const collection = item.collection;

function fileExists(p) { try { return !!p && fs.existsSync(p); } catch(e) { return false; } }

let action = 'healthy';
let publishDone = false;
let donePayload = null;

try {
  if (!uuid) {
    logger.warn(`[reconcile] object without uuid in ${collection} — skipping`);
    bump('skipped_ok');
    return [{ json: { _action: 'healthy', _publish_done: false } }];
  }

  // ============ BankTransaction: parent existence only ============
  if (item.kind === 'banktx') {
    // Skip children already removed by a BankStatement cascade earlier in this
    // same run (avoids a redundant 404 DELETE + misleading failure log). Already
    // counted under deleted_cascade_banktx — do not double-count.
    const cascaded = staticData._cascaded_banktx_uuids || {};
    if (cascaded[uuid]) {
      logger.info(`[reconcile] BankTransaction ${uuid} already cascade-deleted this run — skipping`);
      return [{ json: { _action: 'banktx_orphan', _publish_done: false } }];
    }
    const parentId = item.parent_statement_id;
    let parentAlive = false;
    if (parentId) {
      try {
        // REST GET by id: 200 -> alive, 404 -> gone. Unambiguous.
        const r = await axios.get(`${WEAVIATE}/v1/objects/BankStatement/${parentId}`, { timeout: 10000, validateStatus: () => true });
        if (r.status === 200) parentAlive = true;
        else if (r.status === 404) parentAlive = false;
        else { logger.warn(`[reconcile] BankStatement check HTTP ${r.status} for ${parentId} — keeping BankTransaction ${uuid} (fail-safe)`); parentAlive = true; }
      } catch(e) {
        logger.warn(`[reconcile] BankStatement check failed for ${parentId}: ${e.message} — keeping BankTransaction ${uuid}`);
        parentAlive = true;
      }
    }
    if (parentAlive) {
      bump('skipped_ok');
      return [{ json: { _action: 'healthy', _publish_done: false } }];
    }
    action = 'banktx_orphan';
    logger.info(`[reconcile] banktx_orphan uuid=${uuid} parentStatementId=${parentId || '(none)'} — ${confirm ? 'deleting' : 'DRY-RUN would delete'}`);
    bump('deleted_orphan_banktx'); // planned-or-done
    if (confirm) {
      try {
        await axios.delete(`${WEAVIATE}/v1/objects/BankTransaction/${uuid}`, { timeout: 10000 });
      } catch(e) {
        logger.warn(`[reconcile] DELETE BankTransaction ${uuid} failed: ${e.message}`);
        bump('deleted_orphan_banktx', -1);
        bump('skipped_ok');
      }
    }
    return [{ json: { _action: action, _publish_done: false } }];
  }

  // ============ file-based collections ============
  const storedPath = item.file_path;
  const storedHash = item.file_hash;
  const hashValid = !!storedHash && SHA256_RE.test(String(storedHash));

  // 1) healthy: stored path present and file exists there
  if (fileExists(storedPath)) {
    bump('skipped_ok');
    return [{ json: { _action: 'healthy', _publish_done: false } }];
  }

  // 2) path_drift: hash maps to >= 1 live file
  let livePaths = [];
  if (hashValid) {
    const candidates = Array.isArray(hashToPaths[storedHash]) ? hashToPaths[storedHash].slice() : [];
    if (redisOk) {
      let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
      const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
      try {
        await client.connect();
        const members = await client.sMembers(`alice:dms:hash_to_paths:${storedHash}`);
        for (const m of members) if (!candidates.includes(m)) candidates.push(m);
      } catch(e) {
        logger.warn(`[reconcile] hash_to_paths lookup failed for ${storedHash}: ${e.message}`);
      } finally {
        await client.quit().catch(() => {});
      }
    }
    livePaths = candidates.filter(fileExists);
  }

  if (livePaths.length > 0) {
    livePaths.sort();
    action = 'path_drift';
    const newFilePath = livePaths[0];
    const merged = new Set([...(item.additional_paths || []), ...livePaths.slice(1)]);
    merged.delete(newFilePath);
    const newAdditionalPaths = [...merged];
    const base = newFilePath.split('/').pop();
    const ext = base.includes('.') ? base.split('.').pop().toLowerCase() : null;
    const newFileName = (base && base !== item.file_name) ? base : null;
    const newFileType = (ext && ext !== item.file_type) ? ext : null;

    logger.info(`[reconcile] path_drift uuid=${uuid} collection=${collection} old=${storedPath || '(none)'} new=${newFilePath} — ${confirm ? 'patching' : 'DRY-RUN would patch'}`);
    bump('path_repaired'); // planned-or-done

    if (confirm) {
      let props;
      if (collection === 'Image') {
        // Image schema has no fileName/fileType/additionalPaths — only patch
        // file_path (+ file_name if the property exists on the queried object).
        props = { file_path: newFilePath };
        if (newFileName && item.file_name !== null) props.file_name = newFileName;
        if (newFileType && item.file_type !== null) props.file_type = newFileType;
      } else {
        props = { filePath: newFilePath, additionalPaths: newAdditionalPaths };
        if (newFileName) props.fileName = newFileName;
        if (newFileType) props.fileType = newFileType;
      }
      try {
        await axios.patch(`${WEAVIATE}/v1/objects/${collection}/${uuid}`, { properties: props }, { headers: { 'Content-Type': 'application/json' }, timeout: 10000 });
        publishDone = true;
        donePayload = { document_type: collection, weaviate_uuid: uuid, file_path: newFilePath, file_type: (newFileType || item.file_type) || null, inserted: true };
        bump('done_events_published');
      } catch(e) {
        logger.warn(`[reconcile] PATCH ${collection}/${uuid} failed: ${e.message}`);
        bump('path_repaired', -1);
        bump('skipped_ok');
      }
    }
    return [{ json: { _action: action, _publish_done: publishDone, _done_payload: donePayload } }];
  }

  // 3) healthy (hash broken, path ok): stored path is a live key in path_to_hash
  if (storedPath && pathToHash[storedPath] !== undefined && fileExists(storedPath)) {
    bump('skipped_ok');
    return [{ json: { _action: 'healthy', _publish_done: false } }];
  }

  // 3b) fail-safe: Redis unavailable -> cannot prove there is no live source.
  if (!redisOk) {
    logger.warn(`[reconcile] Redis unavailable — cannot classify uuid=${uuid} collection=${collection}, keeping (fail-safe)`);
    bump('skipped_ok');
    return [{ json: { _action: 'healthy', _publish_done: false } }];
  }

  // 4) orphan: no live source file anywhere -> delete
  action = 'orphan';
  logger.info(`[reconcile] orphan uuid=${uuid} collection=${collection} lastPath=${storedPath || '(none)'} hash=${storedHash || '(none)'} — ${confirm ? 'deleting' : 'DRY-RUN would delete'}`);
  bump('deleted_orphan'); // planned-or-done

  if (confirm) {
    // 4a) BankStatement cascade: delete BankTransaction children first
    if (collection === 'BankStatement') {
      let cursor = null;
      const childUuids = [];
      for (let page = 0; page < 100; page++) {
        const afterClause = cursor ? `, after: "${cursor}"` : '';
        const q = `{ Get { BankTransaction(where: { path: ["parentStatementId"], operator: Equal, valueText: "${uuid}" }, limit: 100${afterClause}) { _additional { id } } } }`;
        try {
          const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: q }, { headers: { 'Content-Type': 'application/json' }, timeout: 15000 });
          const hits = r.data?.data?.Get?.BankTransaction || [];
          for (const h of hits) if (h._additional?.id) childUuids.push(h._additional.id);
          if (hits.length < 100) break;
          cursor = hits[hits.length - 1]._additional.id;
        } catch(e) {
          logger.warn(`[reconcile] cascade GraphQL page ${page} failed for ${uuid}: ${e.message}`);
          break;
        }
      }
      const cascadedSet = staticData._cascaded_banktx_uuids || (staticData._cascaded_banktx_uuids = {});
      for (const cu of childUuids) {
        try {
          await axios.delete(`${WEAVIATE}/v1/objects/BankTransaction/${cu}`, { timeout: 10000 });
          bump('deleted_cascade_banktx');
          cascadedSet[cu] = true;
        } catch(e) {
          logger.warn(`[reconcile] cascade DELETE BankTransaction ${cu} failed: ${e.message}`);
        }
      }
      if (childUuids.length) logger.info(`[reconcile] cascade: deleted BankTransaction children of ${uuid}`);
    }

    // 4b) delete the thumbnail file via the thumbnailer service (n8n has no
    // THUMB_DIR access). Idempotent; a failure never blocks the object delete.
    try {
      const tr = await axios.delete(`${THUMBNAILER}/thumbnail/${uuid}`, { timeout: 10000, validateStatus: () => true });
      if (tr.status >= 200 && tr.status < 300 && tr.data?.deleted) bump('thumbnail_files_removed');
    } catch(e) {
      logger.warn(`[reconcile] thumbnail delete call failed for ${uuid}: ${e.message}`);
    }

    // 4c) delete the Weaviate object
    try {
      await axios.delete(`${WEAVIATE}/v1/objects/${collection}/${uuid}`, { timeout: 10000 });
    } catch(e) {
      logger.warn(`[reconcile] DELETE ${collection}/${uuid} failed: ${e.message}`);
      bump('deleted_orphan', -1);
      bump('skipped_ok');
      return [{ json: { _action: 'orphan', _publish_done: false } }];
    }

    // 4d) clean up dead Redis map entries for this hash — only if no other live
    // file uses it.
    if (hashValid) {
      let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
      const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
      try {
        await client.connect();
        const members = await client.sMembers(`alice:dms:hash_to_paths:${storedHash}`);
        const anyAlive = members.some(fileExists);
        if (!anyAlive) {
          for (const m of members) await client.hDel('alice:dms:path_to_hash', m);
          await client.del(`alice:dms:hash_to_paths:${storedHash}`);
          await client.sRem('alice:dms:processed', storedHash);
          logger.info(`[reconcile] cleaned dead Redis map entries for hash ${storedHash}`);
        }
      } catch(e) {
        logger.warn(`[reconcile] Redis cleanup failed for hash ${storedHash}: ${e.message}`);
      } finally {
        await client.quit().catch(() => {});
      }
    }
  }

  return [{ json: { _action: action, _publish_done: false } }];
} catch(e) {
  logger.warn(`[reconcile] unexpected error for uuid=${uuid} collection=${collection}: ${e.message} — keeping object (fail-safe)`);
  bump('skipped_ok');
  return [{ json: { _action: 'healthy', _publish_done: false } }];
}

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Time Check" } });
// Runs once per object (after the in-flight object is fully processed,
// cascade included). Reads the window from Code: Query Weaviate by node name.
const run = $('Code: Query Weaviate').first().json;
const maxRuntime = run.max_runtime_seconds;
let timeLimitReached = false;
if (maxRuntime !== null && maxRuntime !== undefined) {
  const elapsed = (Date.now() - run.window_start) / 1000;
  timeLimitReached = elapsed >= maxRuntime;
  if (timeLimitReached) {
    logger.info(`[reconcile] Time limit reached (elapsed=${Math.round(elapsed)}s, limit=${maxRuntime}s) — leaving loop, in-flight object already done`);
  }
}
return [{ json: { _time_limit_reached: timeLimitReached } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Build Summary" } });
const redis = require('redis');
const staticData = $getWorkflowStaticData('global');
