const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-reconcile", node: "Code: Release Lock (error)" } });
const redis = require('redis');
const errorData = $input.first().json;

// Best-effort lock release on crash. We do not know the owner token here
// (the run item is gone), so drop the lock only if it is ours by workflow
// tag — otherwise leave it for the TTL. Never DEL another workflow's lock.
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await client.connect();
  const raw = await client.get('alice:dms:processor:lock:run');
  if (raw) {
    let data = null;
    try { data = JSON.parse(raw); } catch(e) {}
    if (data && data.workflow === 'alice-dms-reconcile') {
      await client.del('alice:dms:processor:lock:run');
      logger.info('[reconcile] Released stale lock after error');
    }
  }
} catch(e) {
  logger.info('[reconcile] Lock release on error failed: ' + e.message + ' (TTL will clear it)');
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { workflow: 'alice-dms-reconcile', error: errorData.execution?.error?.message || 'Unknown error', node: errorData.execution?.lastNodeExecuted || 'unknown', timestamp: new Date().toISOString(), execution_id: errorData.execution?.id || null } }];
